function normalize(v){const b=blank();if(!v||typeof v!=='object')return b;['customers','pool','deals','tasks','orders','activities','imports','syncLogs','aiCampaigns','trash'].forEach(k=>b[k]=Array.isArray(v[k])?v[k]:[]);b.settings={...b.settings,...(v.settings||{}),syncRules:{...b.settings.syncRules,...(v.settings?.syncRules||{})},aiDevelopment:{...b.settings.aiDevelopment,...(v.settings?.aiDevelopment||{})}};return b}
