function localInput(v){if(!v)return'';const d=v instanceof Date?v:new Date(v),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
function formatDate(v){if(!v)return'未安排';const d=new Date(v),t=new Date(),tm=new Date();tm.setDate(t.getDate()+1);const p=sameDay(d,t)?'今天':sameDay(d,tm)?'明天':`${d.getMonth()+1} 月 ${d.getDate()} 日`;return p+' '+d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}
function relative(v){if(!v)return'暂无记录';const n=Date.now()-new Date(v).getTime();if(n<60000)return'刚刚';if(n<3600000)return Math.max(1,Math.floor(n/60000))+' 分钟前';if(n<86400000)return Math.floor(n/3600000)+' 小时前';const d=new Date(v);return `${d.getMonth()+1} 月 ${d.getDate()} 日`}
