function authError(error){const message=String(error?.message||'');if(/invalid login/i.test(message))return'邮箱或密码不正确';if(/already registered|already been registered/i.test(message))return'该邮箱已经注册';if(/rate limit|too many requests/i.test(message))return'尝试次数过多，请稍后再试';if(/password/i.test(message))return'密码不符合安全要求，请至少使用8位字符';return'登录服务暂时不可用，请稍后重试'}
function setAuthLoading(loading,message='正在验证登录状态…'){const tabs=$('.auth-tabs'),form=$('#authForm'),help=$('#authHelp');tabs.hidden=loading;form.hidden=loading;help.hidden=loading;$('#authMessage').classList.toggle('loading',loading);if(message!==null)$('#authMessage').textContent=message}
function setAuthMode(mode){authMode=mode;$$('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x.dataset.authTab===mode));$('#authNameField').hidden=mode!=='register';const password=$('#authForm').elements.password;password.minLength=mode==='register'?8:6;password.autocomplete=mode==='register'?'new-password':'current-password';$('#authSubmit').textContent=mode==='register'?'创建并进入 CRM':'登录 CRM';$('#authHelp').textContent=mode==='register'?'新密码至少8位；其他成员须先由管理员添加邮箱后再注册。':'已登录设备会安全恢复有效会话；退出后必须重新输入邮箱和密码。';$('#authMessage').textContent=''}
function showAuth(message=''){$('#authGate').hidden=false;$('#authMessage').textContent=message}
function hideAuth(){$('#authGate').hidden=true}
async function handleAuthSubmit(e){e.preventDefault();const f=new FormData(e.currentTarget),email=String(f.get('email')||'').trim(),password=String(f.get('password')||''),name=String(f.get('name')||'').trim();if(authMode==='register'&&password.length<8){showAuth('新密码至少需要8位字符');return}$('#authSubmit').disabled=true;$('#authMessage').textContent='正在连接云端…';try{if(authMode==='register'){const{data,error}=await supabaseClient.auth.signUp({email,password,options:{data:{name},emailRedirectTo:'https://crm.voltwise.cn/'}});if(error)throw error;if(!data.session){showAuth('注册成功，请打开邮箱确认后再登录。');return}}else{const{error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error}await connectCloud()}catch(error){setAuthLoading(false,null);showAuth(authError(error))}finally{$('#authSubmit').disabled=false}}
async function connectCloud(){const{data:{user}}=await supabaseClient.auth.getUser();if(!user){setAuthLoading(false,'');showAuth();return}currentUser=user;const{data:membership,error}=await supabaseClient.from('team_members').select('*').eq('user_id',user.id).eq('enabled',true).maybeSingle();if(error)throw error;if(!membership){await supabaseClient.auth.signOut();setAuthLoading(false,null);showAuth('该邮箱尚未获得团队授权，请让管理员先在“团队成员”中添加此邮箱。');return}currentMembership=membership;$('#currentMemberName').textContent=membership.name||membership.email;$('#currentAvatar').textContent=(membership.name||membership.email||'成员').slice(0,1).toUpperCase();$('#cloudStatus').textContent='云端已连接';await loadCloudState();await loadTeamMembers();hideAuth();renderAll();applyRoute();subscribeCloud()}
async function loadCloudState(){cloudLoading=true;try{const{data,error}=await supabaseClient.from('crm_state').select('data').eq('team_id',currentMembership.team_id).maybeSingle();if(error)throw error;const remote=data?.data&&Object.keys(data.data).length?normalize(data.data):null;if(remote)state=remote;else if(hasLocalData())await saveCloudState();else state=blank();localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}finally{cloudLoading=false}}
async function saveCloudState(){if(!currentMembership||cloudLoading)return;const payload={team_id:currentMembership.team_id,data:state,updated_by:currentUser.id,updated_at:new Date().toISOString()};const{error}=await supabaseClient.from('crm_state').upsert(payload,{onConflict:'team_id'});if(error){console.error(error);toast('云端保存失败，请检查网络')}else $('#cloudStatus').textContent='云端已同步';syncTeamSettings()}
async function loadTeamMembers(){if(!currentMembership)return;const{data:members,error}=await supabaseClient.from('team_members').select('*').eq('team_id',currentMembership.team_id).order('created_at');if(error)throw error;let invites=[];if(currentMembership.role==='销售管理员'){const result=await supabaseClient.from('team_invites').select('*').eq('team_id',currentMembership.team_id).eq('status','pending').order('created_at');if(!result.error)invites=result.data||[]}state.settings.team=[...(members||[]).map(m=>({id:'member:'+m.user_id,recordType:'member',userId:m.user_id,name:m.name,email:m.email,role:m.role,scope:m.scope,enabled:m.enabled})),...invites.map(i=>({id:'invite:'+i.id,recordType:'invite',inviteId:i.id,name:i.name,email:i.email,role:i.role,scope:i.scope,phone:i.phone,note:i.note,enabled:i.enabled,pending:true}))]}
async function syncTeamSettings(){if(currentMembership?.role!=='销售管理员')return;for(const m of state.settings.team){const values={name:m.name,role:m.role,scope:m.scope,enabled:m.enabled!==false};if(m.recordType==='member')await supabaseClient.from('team_members').update(values).eq('team_id',currentMembership.team_id).eq('user_id',m.userId);if(m.recordType==='invite')await supabaseClient.from('team_invites').update({...values,phone:m.phone||'',note:m.note||''}).eq('id',m.inviteId)}}
let cloudChannel=null;function subscribeCloud(){if(cloudChannel)supabaseClient.removeChannel(cloudChannel);cloudChannel=supabaseClient.channel('crm-team-'+currentMembership.team_id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'crm_state',filter:'team_id=eq.'+currentMembership.team_id},async payload=>{if(payload.new.updated_by===currentUser.id)return;cloudLoading=true;state=normalize(payload.new.data);localStorage.setItem(STORAGE_KEY,JSON.stringify(state));cloudLoading=false;await loadTeamMembers();renderAll();toast('团队数据已更新')}).subscribe()}
async function initCloud(){showAuth();setAuthLoading(true);try{const{data:{session},error}=await supabaseClient.auth.getSession();if(error)throw error;if(session)await connectCloud();else{setAuthLoading(false,'');setAuthMode('login');showAuth()}}catch(error){console.error(error);setAuthLoading(false,null);showAuth('登录状态验证失败，请重新登录。')}}
function route(view,id=null){const h=id?'#customer/'+encodeURIComponent(id):'#'+view;location.hash===h?applyRoute():location.hash=h}
function applyRoute(){const r=location.hash.replace('#','')||'dashboard',[part,id]=r.split('/'),view=part==='customer'?'detail':titles[part]?part:'dashboard';if(part==='customer')selectedCustomerId=decodeURIComponent(id||'');$$('.view').forEach(x=>x.classList.toggle('active',x.id===view));$$('#nav button,[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===(view==='detail'?'customers':view)));$('#pageTitle').textContent=titles[view];$('#sidebar').classList.remove('open');$('#menuOverlay').classList.remove('show');renderAll();if(view==='detail')renderDetail();scrollTo({top:0,behavior:'smooth'})}

function renderCustomers(stage=null,query=null){const f=stage||$('#customerFilters .filter.active')?.dataset.stage||'all',q=(query??$('#customerSearch').value).trim().toLowerCase(),items=state.customers.filter(c=>(f==='all'||c.stage===f)&&(!q||(`${c.company} ${c.contactName} ${c.country}`).toLowerCase().includes(q)));$('#customerList').innerHTML=items.length?items.map(c=>{const h=[...(c.histories||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];return `<article class="customer-card stage-${esc(c.stage)}" data-customer-id="${esc(c.id)}" tabindex="0"><div class="customer-main"><div class="logo">${esc(c.initial)}</div><div class="company"><b>${esc(c.company)}</b><small>${esc(c.country||'')} · ${esc(c.contactName||'未填写联系人')}</small></div><span class="tag customer-stage">${esc(stages[c.stage]?.label||c.stage)}</span></div><div class="customer-card-body"><div class="customer-fact"><span class="cell-label">客户来源</span><span class="cell-value">${esc(c.source||'未填写')}</span></div><div class="customer-fact"><span class="cell-label">负责人</span><span class="cell-value">${esc(c.owner||'未分配')}</span></div><div class="customer-fact"><span class="cell-label">最近跟进</span><span class="cell-value">${esc(relative(h?.createdAt))}</span></div><div class="customer-fact"><span class="cell-label">预计价值</span><span class="cell-value">${esc(c.value||'待评估')}</span></div><div class="customer-fact wide"><span class="cell-label">下一步</span><span class="cell-value">${esc(c.nextAction||'待安排')} · ${esc(formatDate(c.nextFollowAt))}</span></div></div><div class="customer-card-foot"><small>${esc(c.product||'待补充意向产品')}</small><button class="card-open">查看详情</button></div></article>`}).join(''):`<div class="empty"><span>＋</span><p>${q?'没有匹配客户':'客户库为空，请新建客户或导入真实信息。'}</p></div>`;$$('#customerList .customer-card').forEach(x=>x.onclick=()=>route('detail',x.dataset.customerId));$$('#customerFilters .filter').forEach(x=>x.querySelector('.count').textContent=x.dataset.stage==='all'?state.customers.length:state.customers.filter(c=>c.stage===x.dataset.stage).length)}
function taskRow(t,compact=false){const c=customer(t.customerId),d=new Date(t.dueAt);return `<div class="task"><button class="task-check${t.completed?' done':''}" data-task-toggle="${esc(t.id)}">${t.completed?'✓':''}</button><button class="task-link" data-customer-id="${esc(t.customerId||'')}"><b>${esc(t.title)}</b><small>${c?'关联：'+esc(c.company):'未关联客户'}${compact?'':' · '+esc(formatDate(t.dueAt))}</small></button>${compact?`<span class="time">${d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</span>`:''}<button class="mini-btn" data-task-edit="${esc(t.id)}">编辑</button></div>`}
function bindTasks(root=document){root.querySelectorAll('[data-task-toggle]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(x=>x.id===b.dataset.taskToggle);t.completed=!t.completed;save();renderAll();toast(t.completed?'任务已完成':'任务已恢复')});root.querySelectorAll('[data-task-edit]').forEach(b=>b.onclick=()=>openTask(state.tasks.find(x=>x.id===b.dataset.taskEdit)));root.querySelectorAll('.task-link').forEach(b=>b.onclick=()=>customer(b.dataset.customerId)&&route('detail',b.dataset.customerId))}
function renderTasks(){const now=new Date(),week=new Date();week.setDate(now.getDate()+7);const groups=[['今日到期',state.tasks.filter(t=>!t.completed&&sameDay(t.dueAt))],['未来 7 天',state.tasks.filter(t=>!t.completed&&new Date(t.dueAt)>now&&new Date(t.dueAt)<=week&&!sameDay(t.dueAt))],['已完成',state.tasks.filter(t=>t.completed)]];const root=$('#tasks .task-board');root.innerHTML=groups.map(([title,list])=>`<div class="panel task-panel"><div class="panel-head"><h3>${title}</h3><span>${list.length} 项</span></div>${list.length?list.map(t=>taskRow(t)).join(''):'<div class="empty compact"><p>暂无任务</p></div>'}</div>`).join('');bindTasks(root)}
function renderDashboard(){const pending=state.tasks.filter(t=>!t.completed),today=pending.filter(t=>sameDay(t.dueAt)),active=state.deals.filter(d=>d.stage!=='won'),total=state.orders.reduce((s,o)=>s+money(o.amount),0),m=$$('#dashboard .metric strong');[state.customers.length,active.length,pending.length,'$'+total.toLocaleString()].forEach((v,i)=>m[i].textContent=v);$$('#dashboard .pipeline .pipe strong').forEach((x,i)=>x.textContent=state.customers.filter(c=>c.stage===Object.keys(stages)[i]).length);$('#dashboardSummary').textContent=state.customers.length?`今天有 ${today.length} 项待跟进，${active.length} 个活跃商机。`:'系统当前为空，请先新建客户或导入真实线索。';$('#todayChip').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'short'});const list=$('#dashboard .task-list');list.innerHTML=today.length?today.map(t=>taskRow(t,true)).join(''):'<div class="empty compact"><p>今天暂无待办</p></div>';bindTasks(list);const p=$('#activityPanel');p.querySelectorAll('.activity,.empty').forEach(n=>n.remove());if(state.activities.length)state.activities.slice(0,5).forEach(a=>{const c=customer(a.customerId),row=document.createElement('button');row.className='activity';row.innerHTML=`<div class="dot"></div><div><p><b>${esc(c?.company||'系统')}</b> ${esc(a.text)}</p><time>${esc(relative(a.createdAt))}</time></div>`;row.onclick=()=>c&&route('detail',c.id);p.appendChild(row)});else p.insertAdjacentHTML('beforeend','<div class="empty compact"><p>暂无动态</p></div>');$('#channelCard').textContent=state.customers.filter(c=>/名片|展会/.test(c.source)).length;$('#channelWeb').textContent=state.customers.filter(c=>/独立站/.test(c.source)).length;$('#channelAli').textContent=state.customers.filter(c=>/Alibaba/.test(c.source)).length}
function renderPool(){const b=$('#poolBody');$('#poolCount').textContent=state.pool.length;b.innerHTML=state.pool.length?state.pool.map(l=>`<tr><td><b>${esc(l.company)}</b><br><small>${esc(l.contact||'未填写联系人')}</small></td><td>${esc(l.source)}</td><td>${esc(l.country||'未填写')}</td><td>${esc(l.product||'未填写')}</td><td>${esc(relative(l.createdAt))}</td><td><button class="ghost" data-claim="${esc(l.id)}">认领</button> <button class="mini-btn" data-lead-edit="${esc(l.id)}">编辑</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty compact"><p>开发池为空，可导入真实线索。</p></div></td></tr>';b.querySelectorAll('[data-claim]').forEach(x=>x.onclick=()=>claimLead(x.dataset.claim));b.querySelectorAll('[data-lead-edit]').forEach(x=>x.onclick=()=>openLead(state.pool.find(l=>l.id===x.dataset.leadEdit)))}
function renderAI(){const root=$('#aiCampaigns');if(!root)return;$('#aiCampaignCount').textContent=`${state.aiCampaigns.length} 个计划`;root.innerHTML=state.aiCampaigns.length?state.aiCampaigns.map(x=>`<div class="panel campaign-card"><div style="display:flex;justify-content:space-between;gap:8px"><div><h3>${esc(x.name)}</h3><span class="status orange">${esc(x.status||'待连接数据源')}</span></div><button class="mini-btn" data-ai-edit="${esc(x.id)}">编辑</button></div><p>${esc(x.products||'未填写产品关键词')} · ${esc(x.countries||'未填写目标国家')}</p><div class="campaign-meta"><div><label>客户类型</label><b>${esc(x.customerTypes||'进口商/批发商')}</b></div><div><label>每日目标</label><b>${esc(x.dailyLimit||20)} 家</b></div></div><div class="campaign-actions"><button class="ghost" data-ai-import="${esc(x.id)}">手动导入</button><button class="primary" data-ai-run="${esc(x.id)}">开始开发</button></div></div>`).join(''):'<div class="panel empty" style="grid-column:1/-1"><p>暂无开发计划。先设置产品、国家和每日目标；接入真实数据源后即可自动运行。</p></div>';root.querySelectorAll('[data-ai-edit]').forEach(b=>b.onclick=()=>openAiCampaign(state.aiCampaigns.find(x=>x.id===b.dataset.aiEdit)));root.querySelectorAll('[data-ai-import]').forEach(b=>b.onclick=()=>{route('pool');openLead()});root.querySelectorAll('[data-ai-run]').forEach(b=>b.onclick=()=>runAiCampaign(state.aiCampaigns.find(x=>x.id===b.dataset.aiRun)))}
function openAiCampaign(x=null){openAction(x?'编辑 AI 开发计划':'新建 AI 开发计划',[{name:'name',label:'计划名称',required:true},{name:'products',label:'产品关键词（中英文）',required:true},{name:'countries',label:'目标国家/地区',required:true},{name:'customerTypes',label:'目标客户类型',required:true},{name:'dailyLimit',label:'每日开发数量',type:'number',required:true},{name:'notes',label:'排除条件与备注',type:'textarea'}],d=>{const v=Object.fromEntries(d);v.dailyLimit=Math.max(1,Number(v.dailyLimit)||20);if(x)Object.assign(x,v);else state.aiCampaigns.unshift({id:uid('ai'),...v,status:'待连接数据源',createdAt:new Date().toISOString()});toast(x?'开发计划已更新':'开发计划已建立；等待接入真实数据源')},x||{customerTypes:'进口商、批发商、品牌商',dailyLimit:20})}
function runAiCampaign(x){if(!x)return;const cfg=state.settings.aiDevelopment;if(!cfg?.searchConnected||!cfg?.aiConnected){x.status='待连接数据源';save();renderAI();toast('尚未连接真实搜索与 AI 服务，不会生成虚假客户');return}toast('开发任务已提交，合格客户将进入开发池')}
function openEmail(c){if(!c?.email){toast('该客户尚未填写邮箱');return}const product=c.product||'your sourcing requirements',contact=c.contactName||'Sir or Madam',subject=`Follow-up regarding ${product}`,body=`Dear ${contact},\n\nI am following up regarding ${product}. We would be glad to learn more about your requirements, target quantity and expected delivery schedule.\n\nPlease let us know a convenient time to discuss the details.\n\nBest regards,`;openAction('邮件跟进客户',[{name:'to',label:'收件人',type:'email',required:true},{name:'subject',label:'邮件主题',required:true,full:true},{name:'body',label:'邮件正文',type:'textarea'}],d=>{const to=String(d.get('to')||'').trim(),url=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(d.get('subject')||'')}&body=${encodeURIComponent(d.get('body')||'')}`;log(c.id,'已打开邮件草稿（待业务员确认发送）');location.href=url;toast('已打开邮箱草稿；发送后请记录跟进')},{to:c.email,subject,body});$('#saveAction').textContent='打开邮箱'}
function claimLead(id){const l=state.pool.find(x=>x.id===id);if(!l)return;const c={id:uid('c'),stage:'lead',initial:initials(l.company),company:l.company,contactName:l.contact||'',title:'联系人',country:l.country||'',source:l.source||'开发池',value:'待评估',owner:'未分配',email:l.email||'',phone:l.phone||'',product:l.product||'',notes:l.notes||'',nextFollowAt:null,nextAction:'待安排首次联系',histories:[]};state.customers.unshift(c);state.pool=state.pool.filter(x=>x.id!==id);log(c.id,'从开发池认领并建档');save();renderAll();route('detail',c.id);toast('线索已转入客户管理')}
function renderDeals(){const root=$('#dealsBoard');root.innerHTML=['contact','quote','negotiate','won'].map(s=>{const list=state.deals.filter(d=>d.stage===s),sum=list.reduce((n,d)=>n+money(d.value),0);return `<div class="kan-col"><div class="kan-head"><b>${stages[s].label}</b><span>${list.length} · $${sum.toLocaleString()}</span></div>${list.length?list.map(d=>`<div class="deal" data-deal="${esc(d.id)}"><b>${esc(d.title)}</b><p>${esc(customer(d.customerId)?.company||'未关联')} · ${esc(d.nextAction||'待安排')}</p><div class="progress"><i style="width:${stages[s].progress}%"></i></div><div class="deal-foot"><span class="money">${esc(d.value)}</span><button class="mini-btn">编辑</button></div></div>`).join(''):'<div class="empty compact"><p>暂无商机</p></div>'}</div>`}).join('');root.querySelectorAll('[data-deal]').forEach(x=>x.onclick=()=>openDeal(state.deals.find(d=>d.id===x.dataset.deal)))}
function renderOrders(){const b=$('#ordersBody');b.innerHTML=state.orders.length?state.orders.map(o=>`<tr><td><b>${esc(o.number)}</b></td><td>${esc(customer(o.customerId)?.company||'未关联')}</td><td>${esc(o.channel)}</td><td><b>${esc(o.amount)}</b></td><td>${esc(o.term)}</td><td><span class="status">${esc(o.status)}</span></td><td>${esc(o.deliveryAt||'未安排')}</td><td><button class="mini-btn" data-order-edit="${esc(o.id)}">编辑</button></td></tr>`).join(''):'<tr><td colspan="8"><div class="empty compact"><p>暂无订单，请点击“新建订单”。</p></div></td></tr>';b.querySelectorAll('[data-order-edit]').forEach(x=>x.onclick=()=>openOrder(state.orders.find(o=>o.id===x.dataset.orderEdit)))}
function renderSync(){const r=state.settings.syncRules;$('#syncCards').innerHTML=[['website','W','独立站表单'],['alibaba','A','Alibaba.com']].map(([k,logo,name])=>`<div class="panel sync-card"><div class="sync-brand"><div class="sync-logo${k==='alibaba'?' ali':''}">${logo}</div><div><h3>${name}</h3><p>${r[k]?'已配置本地同步规则':'尚未连接正式账号'}</p></div><span class="status" style="margin-left:auto">${r[k]?'已启用':'未连接'}</span></div><div class="sync-stats"><div class="sync-stat"><label>今日新增</label><b>0</b></div><div class="sync-stat"><label>本月新增</label><b>0</b></div><div class="sync-stat"><label>待处理</label><b>0</b></div></div><div class="sync-foot"><small>${r[k]?'等待正式接口授权':'请先配置渠道连接'}</small><button class="ghost" data-connect="${k}">配置连接</button></div></div>`).join('');$$('[data-connect]').forEach(x=>x.onclick=()=>openSync(x.dataset.connect));$('#syncLogBody').innerHTML=state.syncLogs.length?state.syncLogs.map(l=>`<div class="settings-row"><div><b>${esc(l.channel)} · ${esc(l.result)}</b><small>${esc(formatDate(l.createdAt))} · ${esc(l.note)}</small></div></div>`).join(''):'<div class="empty compact"><p>暂无同步记录</p></div>'}
function renderReports(){const won=state.deals.filter(d=>d.stage==='won').length,q=state.deals.filter(d=>['quote','negotiate','won'].includes(d.stage)).length,conv=state.pool.length+state.customers.length?Math.round(state.customers.length/(state.pool.length+state.customers.length)*100):0,win=q?Math.round(won/q*100):0,total=state.orders.reduce((n,o)=>n+money(o.amount),0);$('#reportMetrics').innerHTML=[['线索转客户率',conv+'%'],['报价赢单率',win+'%'],['客户总数',state.customers.length],['订单总额','$'+total.toLocaleString()]].map(([l,v])=>`<div class="metric"><div class="metric-top"><span>${l}</span></div><strong>${v}</strong><span class="delta">当前数据</span></div>`).join('');const sources={};state.customers.forEach(c=>sources[c.source]=(sources[c.source]||0)+1);$('#channelReport').innerHTML=Object.keys(sources).length?`<div class="pipeline" style="padding:30px 22px">${Object.entries(sources).map(([n,c])=>`<div class="pipe"><div class="bar" style="height:${20+c*12}px"></div><label>${esc(n)}</label><strong>${c}</strong></div>`).join('')}</div>`:'<div class="empty compact"><p>暂无可统计数据</p></div>'}

function renderSettings(){const root=$('#settingsContent');$$('.setting-card').forEach(b=>b.classList.toggle('active',b.dataset.setting===activeSetting));if(activeSetting==='team'){const enabled=state.settings.team.filter(m=>m.enabled!==false).length;root.innerHTML=`<div class="settings-body"><div class="settings-title"><div><h3>成员管理</h3><small>当前 ${enabled} 名启用成员 · 管理角色和数据范围</small></div><button class="primary" id="addMember">＋ 新增成员</button></div><div class="settings-list">${state.settings.team.length?state.settings.team.map(m=>`<div class="settings-row"><div><b>${esc(m.name)} ${m.enabled===false?'<span class="status">已停用</span>':''}</b><small>${esc(m.role)} · ${esc(m.scope||'仅本人客户')} · ${esc(m.email||'未填写邮箱')}</small></div><div class="row-actions"><button class="toggle ${m.enabled!==false?'on':''}" data-member-toggle="${esc(m.id)}">${m.enabled!==false?'已启用':'已停用'}</button><button class="mini-btn" data-member="${esc(m.id)}">编辑</button><button class="mini-btn" data-member-remove="${esc(m.id)}">移除</button></div></div>`).join(''):'<div class="empty compact"><p>暂无成员，点击右上角“新增成员”。</p></div>'}</div><div class="settings-row" style="margin-top:12px"><div><b>账号开通说明</b><small>这里先保存成员与权限配置；接入云端登录后，邮箱才会收到正式邀请。</small></div></div></div>`;$('#addMember').onclick=()=>openMember();root.querySelectorAll('[data-member]').forEach(x=>x.onclick=()=>openMember(state.settings.team.find(m=>m.id===x.dataset.member)));root.querySelectorAll('[data-member-toggle]').forEach(x=>x.onclick=()=>{const m=state.settings.team.find(y=>y.id===x.dataset.memberToggle);m.enabled=m.enabled===false;save();renderSettings();toast(m.enabled?'成员已启用':'成员已停用')});root.querySelectorAll('[data-member-remove]').forEach(x=>x.onclick=()=>removeMember(x.dataset.memberRemove))}if(activeSetting==='fields'){root.innerHTML=`<div class="settings-body"><div class="settings-title"><div><h3>字段配置</h3><small>新增业务所需的自定义字段</small></div><button class="primary" id="addField">＋ 新增字段</button></div><div class="settings-list">${state.settings.customFields.length?state.settings.customFields.map(f=>`<div class="settings-row"><div><b>${esc(f.name)}</b><small>${esc(f.module)} · ${esc(f.type)}</small></div><div class="row-actions"><button class="toggle ${f.enabled?'on':''}" data-field-toggle="${esc(f.id)}">${f.enabled?'已启用':'已停用'}</button><button class="mini-btn" data-field="${esc(f.id)}">编辑</button></div></div>`).join(''):'<div class="empty compact"><p>暂无自定义字段</p></div>'}</div></div>`;$('#addField').onclick=()=>openField();root.querySelectorAll('[data-field-toggle]').forEach(x=>x.onclick=()=>{const f=state.settings.customFields.find(y=>y.id===x.dataset.fieldToggle);f.enabled=!f.enabled;save();renderSettings()});root.querySelectorAll('[data-field]').forEach(x=>x.onclick=()=>openField(state.settings.customFields.find(f=>f.id===x.dataset.field)))}if(activeSetting==='syncRules'){const r=state.settings.syncRules;root.innerHTML=`<div class="settings-body"><div class="settings-title"><div><h3>同步规则</h3><small>管理渠道开关与客户查重</small></div></div><div class="settings-list"><div class="settings-row"><div><b>独立站表单</b><small>新询盘进入客户开发池</small></div><button class="toggle ${r.website?'on':''}" data-sync="website">${r.website?'已启用':'未启用'}</button></div><div class="settings-row"><div><b>Alibaba</b><small>询盘和订单进入同步中心</small></div><button class="toggle ${r.alibaba?'on':''}" data-sync="alibaba">${r.alibaba?'已启用':'未启用'}</button></div><div class="settings-row"><div><b>自动查重</b><small>${esc(r.dedupe)}</small></div><button class="mini-btn" id="dedupe">编辑</button></div></div></div>`;root.querySelectorAll('[data-sync]').forEach(x=>x.onclick=()=>{r[x.dataset.sync]=!r[x.dataset.sync];save();renderAll();toast('同步规则已更新')});$('#dedupe').onclick=openDedupe}if(activeSetting==='stages'){root.innerHTML=`<div class="settings-body"><div class="settings-title"><div><h3>销售阶段</h3><small>调整阶段名称和提醒天数</small></div></div><div class="settings-list">${state.settings.stages.map(s=>`<div class="settings-row"><div><b>${esc(s.label)}</b><small>超过 ${esc(s.recycleDays)} 天未跟进提醒</small></div><button class="mini-btn" data-stage="${esc(s.key)}">编辑</button></div>`).join('')}</div></div>`;root.querySelectorAll('[data-stage]').forEach(x=>x.onclick=()=>openStage(state.settings.stages.find(s=>s.key===x.dataset.stage)))}}
function renderDetail(){const c=customer(selectedCustomerId),root=$('#detail .detail-grid');if(!c){root.innerHTML='<div class="panel empty"><p>客户不存在或已移除。</p></div>';return}const h=[...(c.histories||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));root.innerHTML=`<div class="panel"><div class="detail-hero"><div class="detail-company"><div class="logo">${esc(c.initial)}</div><div><h2>${esc(c.company)}</h2><p>${esc(c.country||'未填写地区')} · ${esc(c.product||'待补充产品')}</p></div><div class="detail-actions"><button class="ghost" id="editCustomer">编辑客户</button><button class="primary" id="followBtn">＋ 添加跟进</button></div></div></div><div class="tabs"><button class="tab active" data-tab="overview">概览</button><button class="tab" data-tab="deals">商机 ${state.deals.filter(d=>d.customerId===c.id).length}</button><button class="tab" data-tab="orders">订单 ${state.orders.filter(o=>o.customerId===c.id).length}</button><button class="tab" data-tab="history">跟进 ${h.length}</button></div><div class="detail-body" id="detailTab"></div></div><aside class="panel"><div class="panel-head"><h3>跟进时间线</h3><button id="miniFollow">＋ 记录</button></div><div class="timeline">${h.length?h.map(x=>`<div class="timeline-item"><b>${esc(x.type)}</b><p>${esc(x.summary)}</p><time>${esc(formatDate(x.createdAt))}</time></div>`).join(''):'<div class="empty compact"><p>暂无跟进记录</p></div>'}</div></aside>`;$('#editCustomer').onclick=()=>openCustomer(c);$('#followBtn').onclick=$('#miniFollow').onclick=openFollow;root.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>renderDetailTab(c,x.dataset.tab));renderDetailTab(c,'overview')}
function renderDetailTab(c,tab){const b=$('#detailTab');$$('#detail .tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));if(tab==='overview')b.innerHTML=`<div class="field-grid"><div class="field"><label>客户负责人</label><div>${esc(c.owner||'未分配')}</div></div><div class="field"><label>当前阶段</label><div>${esc(stages[c.stage]?.label)}</div></div><div class="field"><label>预计价值</label><div>${esc(c.value||'待评估')}</div></div><div class="field"><label>主要联系人</label><div>${esc(c.contactName||'未填写')} · ${esc(c.title||'')}</div></div><div class="field"><label>邮箱</label><div>${esc(c.email||'未填写')}</div></div><div class="field"><label>WhatsApp</label><div>${esc(c.phone||'未填写')}</div></div><div class="field"><label>下次跟进</label><div>${esc(formatDate(c.nextFollowAt))}</div></div><div class="field"><label>下一步动作</label><div>${esc(c.nextAction||'待安排')}</div></div><div class="field"><label>客户备注</label><div>${esc(c.notes||'暂无备注')}</div></div></div>`;if(tab==='deals')b.innerHTML=state.deals.filter(d=>d.customerId===c.id).map(d=>`<div class="settings-row"><div><b>${esc(d.title)}</b><small>${esc(stages[d.stage].label)} · ${esc(d.value)}</small></div><button class="mini-btn" data-detail-deal="${d.id}">编辑</button></div>`).join('')||'<div class="empty compact"><p>暂无关联商机</p></div>';if(tab==='orders')b.innerHTML=state.orders.filter(o=>o.customerId===c.id).map(o=>`<div class="settings-row"><div><b>${esc(o.number)}</b><small>${esc(o.status)} · ${esc(o.amount)}</small></div><button class="mini-btn" data-detail-order="${o.id}">编辑</button></div>`).join('')||'<div class="empty compact"><p>暂无关联订单</p></div>';if(tab==='history')b.innerHTML=(c.histories||[]).map(x=>`<div class="settings-row"><div><b>${esc(x.type)}</b><small>${esc(x.summary)} · ${esc(formatDate(x.createdAt))}</small></div></div>`).join('')||'<div class="empty compact"><p>暂无跟进记录</p></div>';b.querySelectorAll('[data-detail-deal]').forEach(x=>x.onclick=()=>openDeal(state.deals.find(d=>d.id===x.dataset.detailDeal)));b.querySelectorAll('[data-detail-order]').forEach(x=>x.onclick=()=>openOrder(state.orders.find(o=>o.id===x.dataset.detailOrder)))}
const trashTypes={customer:{array:'customers',label:'客户'},lead:{array:'pool',label:'开发池线索'},deal:{array:'deals',label:'商机'},task:{array:'tasks',label:'任务'},order:{array:'orders',label:'订单'},ai:{array:'aiCampaigns',label:'AI开发计划'},field:{label:'自定义字段'},history:{label:'跟进记录'}};
const canArchive=()=>currentMembership?.role!=='只读成员';
const isAdmin=()=>currentMembership?.role==='销售管理员';
function trashCollection(type){return type==='field'?state.settings.customFields:state[trashTypes[type]?.array]}
function trashLabel(type,record){if(type==='customer'||type==='lead')return record.company;if(type==='deal'||type==='task')return record.title;if(type==='order')return record.number;if(type==='ai'||type==='field')return record.name;if(type==='history')return `${record.type||'跟进'}：${record.summary||''}`;return record.id}
function moveToTrash(type,id,batchId=null,parentId=null){let record;if(type==='history'){const parent=customer(parentId);if(!parent)return false;const index=(parent.histories||[]).findIndex(x=>x.id===id);if(index<0)return false;record=parent.histories.splice(index,1)[0]}else{const list=trashCollection(type),index=list?.findIndex(x=>x.id===id)??-1;if(index<0)return false;record=list.splice(index,1)[0]}state.trash.unshift({id:uid('trash'),type,sourceId:id,label:trashLabel(type,record),record,parentId,batchId,deletedAt:new Date().toISOString(),deletedBy:currentMembership?.name||currentMembership?.email||'当前成员'});return true}
function archiveRecord(type,id){if(!canArchive()){toast('只读成员不能归档数据');return}if(type==='customer'){if(!isAdmin()){toast('只有销售管理员可以删除客户');return}const related={deal:state.deals.filter(x=>x.customerId===id),task:state.tasks.filter(x=>x.customerId===id),order:state.orders.filter(x=>x.customerId===id)},c=customer(id);if(!c)return;const message=`确定将客户“${c.company}”移入回收站吗？\n关联的 ${related.deal.length} 个商机、${related.task.length} 个任务和 ${related.order.length} 个订单会一并移入，可在“系统 → 回收站”恢复。`;if(!confirm(message))return;const batchId=uid('batch');Object.entries(related).forEach(([kind,items])=>items.forEach(x=>moveToTrash(kind,x.id,batchId,id)));moveToTrash('customer',id,batchId);selectedCustomerId=null;save();renderAll();route('customers');toast('客户及关联内容已移入回收站');return}const record=trashCollection(type)?.find(x=>x.id===id);if(!record||!confirm(`确定将“${trashLabel(type,record)}”移入回收站吗？`))return;moveToTrash(type,id);save();renderAll();toast('已移入回收站，可在30天内恢复')}
function restoreTrash(id){if(!canArchive()){toast('只读成员不能恢复数据');return}const item=state.trash.find(x=>x.id===id);if(!item)return;if(item.type==='customer'&&!isAdmin()){toast('只有销售管理员可以恢复客户');return}let items=item.type==='customer'&&item.batchId?state.trash.filter(x=>x.batchId===item.batchId):[item];items=[...items].sort((a,b)=>(a.type==='customer'?-1:0)-(b.type==='customer'?-1:0));const restored=[];for(const entry of items){if(entry.type==='history'){const parent=customer(entry.parentId);if(!parent){toast('请先恢复该跟进记录所属客户');continue}parent.histories=parent.histories||[];if(!parent.histories.some(x=>x.id===entry.sourceId))parent.histories.unshift(entry.record);restored.push(entry.id);continue}const list=trashCollection(entry.type);if(!list)continue;if(!list.some(x=>x.id===entry.sourceId))list.unshift(entry.record);restored.push(entry.id)}state.trash=state.trash.filter(x=>!restored.includes(x.id));save();renderAll();toast(restored.length>1?'客户及关联内容已恢复':'内容已恢复')}
function purgeTrash(id){if(currentMembership?.role!=='销售管理员'){toast('只有管理员可以彻底删除');return}const item=state.trash.find(x=>x.id===id);if(!item)return;const age=Date.now()-new Date(item.deletedAt).getTime();if(age<30*86400000){toast('保护期未满30天，暂不能彻底删除');return}if(!confirm(`彻底删除“${item.label}”后无法恢复，确定继续吗？`))return;const ids=item.type==='customer'&&item.batchId?state.trash.filter(x=>x.batchId===item.batchId).map(x=>x.id):[id];state.trash=state.trash.filter(x=>!ids.includes(x.id));save();renderTrash();toast('已彻底删除')}
function renderTrash(){const body=$('#trashBody');if(!body)return;const admin=isAdmin(),items=[...state.trash].sort((a,b)=>new Date(b.deletedAt)-new Date(a.deletedAt));body.innerHTML=items.length?items.map(x=>{const elapsed=Math.floor((Date.now()-new Date(x.deletedAt).getTime())/86400000),days=Math.max(0,30-elapsed),canRestore=x.type!=='customer'||admin;return `<tr><td><b>${esc(x.label||'未命名内容')}</b>${x.batchId?'<br><small>关联批次</small>':''}</td><td>${esc(trashTypes[x.type]?.label||x.type)}</td><td>${esc(new Date(x.deletedAt).toLocaleString('zh-CN',{hour12:false}))}</td><td>${esc(x.deletedBy||'未知')}</td><td>${days?`${days} 天`:'已满30天'}</td><td>${canRestore?`<button class="ghost" data-trash-restore="${esc(x.id)}">恢复</button>`:'<small>仅管理员可恢复</small>'}${admin?` <button class="danger-btn" data-trash-purge="${esc(x.id)}"${days?' disabled title="保护期未满"':''}>彻底删除</button>`:''}</td></tr>`}).join(''):'<tr><td colspan="6"><div class="empty compact"><p>回收站为空</p></div></td></tr>';body.querySelectorAll('[data-trash-restore]').forEach(x=>x.onclick=()=>restoreTrash(x.dataset.trashRestore));body.querySelectorAll('[data-trash-purge]').forEach(x=>x.onclick=()=>purgeTrash(x.dataset.trashPurge))}
function openHistoryManager(c){const histories=c.histories||[];if(!histories.length){toast('暂无跟进记录');return}openAction('归档跟进记录',[{name:'historyId',label:'选择跟进记录',type:'select',required:true,options:histories.map(x=>({value:x.id,label:`${formatDate(x.createdAt)} · ${x.type} · ${x.summary}`}))}],d=>{moveToTrash('history',d.get('historyId'),null,c.id);toast('跟进记录已移入回收站')})}
function addArchiveButton(anchor,type,id,container=null){if(!anchor||anchor.dataset.archiveReady)return;anchor.dataset.archiveReady='1';const button=document.createElement('button');button.className='danger-btn';button.textContent='归档';button.onclick=e=>{e.preventDefault();e.stopPropagation();archiveRecord(type,id)};(container||anchor.parentElement).appendChild(button)}
