function decorateArchiveActions(){if(!canArchive())return;$$('[data-lead-edit]').forEach(x=>addArchiveButton(x,'lead',x.dataset.leadEdit));$$('[data-task-edit]').forEach(x=>addArchiveButton(x,'task',x.dataset.taskEdit));$$('[data-order-edit]').forEach(x=>addArchiveButton(x,'order',x.dataset.orderEdit));$$('[data-ai-edit]').forEach(x=>addArchiveButton(x,'ai',x.dataset.aiEdit));$$('[data-field]').forEach(x=>addArchiveButton(x,'field',x.dataset.field));$$('[data-deal]').forEach(x=>{const foot=x.querySelector('.deal-foot'),edit=foot?.querySelector('button');if(edit)addArchiveButton(edit,'deal',x.dataset.deal,foot)});const c=customer(selectedCustomerId),actions=$('#detail .detail-actions');if(c&&actions){addCustomerAdminMenu(c,actions);if((c.histories||[]).length&&!$('#manageHistory')){const history=document.createElement('button');history.className='ghost';history.id='manageHistory';history.textContent='管理跟进';history.onclick=()=>openHistoryManager(c);actions.appendChild(history)}}}
